CREATE TYPE "KanbanBoardVisibility" AS ENUM ('PRIVATE', 'TEAM', 'ORGANIZATION');
CREATE TYPE "KanbanBoardStatus" AS ENUM ('ACTIVE', 'ARCHIVED');
CREATE TYPE "KanbanTaskPriority" AS ENUM ('LOW', 'NORMAL', 'HIGH', 'URGENT');
CREATE TYPE "KanbanRecurrenceFrequency" AS ENUM ('DAILY', 'WEEKLY', 'MONTHLY');
CREATE TYPE "EnterpriseStatus" AS ENUM ('ACTIVE', 'SUSPENDED', 'INACTIVE');
CREATE TYPE "ClientStatus" AS ENUM ('ACTIVE', 'INACTIVE');
CREATE TYPE "ProjectStatus" AS ENUM ('PLANNING', 'ACTIVE', 'ON_HOLD', 'COMPLETED', 'CANCELLED');
CREATE TYPE "AssistanceStatus" AS ENUM ('OPEN', 'TRIAGE', 'SCHEDULED', 'IN_PROGRESS', 'WAITING_CLIENT', 'RESOLVED', 'CANCELLED');

CREATE TABLE "Enterprise" ("id" TEXT NOT NULL, "legalName" TEXT NOT NULL, "tradeName" TEXT, "document" TEXT, "slug" TEXT NOT NULL, "email" TEXT, "phone" TEXT, "status" "EnterpriseStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, CONSTRAINT "Enterprise_pkey" PRIMARY KEY ("id"));
CREATE UNIQUE INDEX "Enterprise_document_key" ON "Enterprise"("document");
CREATE UNIQUE INDEX "Enterprise_slug_key" ON "Enterprise"("slug");
CREATE INDEX "Enterprise_status_idx" ON "Enterprise"("status");
INSERT INTO "Enterprise" ("id","legalName","tradeName","slug","updatedAt") VALUES ('default-enterprise','Gestium','Gestium','gestium',CURRENT_TIMESTAMP) ON CONFLICT DO NOTHING;
ALTER TABLE "Organization" ADD COLUMN "enterpriseId" TEXT;
UPDATE "Organization" SET "enterpriseId"='default-enterprise' WHERE "enterpriseId" IS NULL;
ALTER TABLE "Organization" ALTER COLUMN "enterpriseId" SET NOT NULL;
CREATE INDEX "Organization_enterpriseId_idx" ON "Organization"("enterpriseId");
ALTER TABLE "Organization" ADD CONSTRAINT "Organization_enterpriseId_fkey" FOREIGN KEY ("enterpriseId") REFERENCES "Enterprise"("id") ON DELETE RESTRICT ON UPDATE CASCADE;

CREATE TABLE "Client" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "document" TEXT, "email" TEXT, "phone" TEXT, "address" TEXT, "notes" TEXT, "status" "ClientStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "organizationId" TEXT NOT NULL, CONSTRAINT "Client_pkey" PRIMARY KEY ("id"));
CREATE TABLE "Project" ("id" TEXT NOT NULL, "code" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "status" "ProjectStatus" NOT NULL DEFAULT 'PLANNING', "startAt" TIMESTAMP(3), "dueAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "organizationId" TEXT NOT NULL, "clientId" TEXT NOT NULL, "managerId" TEXT, CONSTRAINT "Project_pkey" PRIMARY KEY ("id"));
CREATE TABLE "AssistanceTicket" ("id" TEXT NOT NULL, "number" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT NOT NULL, "status" "AssistanceStatus" NOT NULL DEFAULT 'OPEN', "priority" "KanbanTaskPriority" NOT NULL DEFAULT 'NORMAL', "dueAt" TIMESTAMP(3), "resolvedAt" TIMESTAMP(3), "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "organizationId" TEXT NOT NULL, "clientId" TEXT NOT NULL, "projectId" TEXT, "assigneeId" TEXT, "createdById" TEXT NOT NULL, CONSTRAINT "AssistanceTicket_pkey" PRIMARY KEY ("id"));

CREATE TABLE "KanbanBoard" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "description" TEXT, "team" TEXT, "visibility" "KanbanBoardVisibility" NOT NULL DEFAULT 'TEAM', "status" "KanbanBoardStatus" NOT NULL DEFAULT 'ACTIVE', "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "organizationId" TEXT NOT NULL, "ownerId" TEXT NOT NULL, "createdById" TEXT NOT NULL, CONSTRAINT "KanbanBoard_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KanbanColumn" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "position" INTEGER NOT NULL, "cardLimit" INTEGER, "isInitial" BOOLEAN NOT NULL DEFAULT false, "isCompletion" BOOLEAN NOT NULL DEFAULT false, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "boardId" TEXT NOT NULL, CONSTRAINT "KanbanColumn_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KanbanTask" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "team" TEXT, "sector" TEXT, "priority" "KanbanTaskPriority" NOT NULL DEFAULT 'NORMAL', "startAt" TIMESTAMP(3), "dueAt" TIMESTAMP(3), "completedAt" TIMESTAMP(3), "observations" TEXT, "position" INTEGER NOT NULL DEFAULT 0, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "columnId" TEXT NOT NULL, "assigneeId" TEXT, "createdById" TEXT NOT NULL, "requisitionId" TEXT, "agendaEventId" TEXT, "clientId" TEXT, "projectId" TEXT, "assistanceId" TEXT, CONSTRAINT "KanbanTask_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KanbanTaskParticipant" ("taskId" TEXT NOT NULL, "userId" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT "KanbanTaskParticipant_pkey" PRIMARY KEY ("taskId","userId"));
CREATE TABLE "KanbanLabel" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "color" TEXT NOT NULL DEFAULT 'slate', "boardId" TEXT NOT NULL, "organizationId" TEXT NOT NULL, CONSTRAINT "KanbanLabel_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KanbanTaskLabel" ("taskId" TEXT NOT NULL, "labelId" TEXT NOT NULL, CONSTRAINT "KanbanTaskLabel_pkey" PRIMARY KEY ("taskId","labelId"));
CREATE TABLE "KanbanChecklistItem" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "completed" BOOLEAN NOT NULL DEFAULT false, "position" INTEGER NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "taskId" TEXT NOT NULL, CONSTRAINT "KanbanChecklistItem_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KanbanSubtask" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "completed" BOOLEAN NOT NULL DEFAULT false, "dueAt" TIMESTAMP(3), "observation" TEXT, "position" INTEGER NOT NULL, "taskId" TEXT NOT NULL, "assigneeId" TEXT, CONSTRAINT "KanbanSubtask_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KanbanComment" ("id" TEXT NOT NULL, "body" TEXT NOT NULL, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "taskId" TEXT NOT NULL, "authorId" TEXT NOT NULL, CONSTRAINT "KanbanComment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KanbanAttachment" ("id" TEXT NOT NULL, "name" TEXT NOT NULL, "url" TEXT NOT NULL, "mimeType" TEXT, "size" INTEGER, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "taskId" TEXT NOT NULL, CONSTRAINT "KanbanAttachment_pkey" PRIMARY KEY ("id"));
CREATE TABLE "KanbanRecurrence" ("id" TEXT NOT NULL, "title" TEXT NOT NULL, "description" TEXT, "priority" "KanbanTaskPriority" NOT NULL DEFAULT 'NORMAL', "frequency" "KanbanRecurrenceFrequency" NOT NULL, "interval" INTEGER NOT NULL DEFAULT 1, "weekdays" INTEGER[], "nextRunAt" TIMESTAMP(3) NOT NULL, "endAt" TIMESTAMP(3), "active" BOOLEAN NOT NULL DEFAULT true, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "updatedAt" TIMESTAMP(3) NOT NULL, "organizationId" TEXT NOT NULL, "columnId" TEXT NOT NULL, "assigneeId" TEXT, "createdById" TEXT NOT NULL, CONSTRAINT "KanbanRecurrence_pkey" PRIMARY KEY ("id"));
ALTER TABLE "KanbanTask" ADD COLUMN "recurrenceId" TEXT, ADD COLUMN "occurrenceAt" TIMESTAMP(3);
CREATE TABLE "KanbanHistory" ("id" TEXT NOT NULL, "action" TEXT NOT NULL, "fromValue" JSONB, "toValue" JSONB, "createdAt" TIMESTAMP(3) NOT NULL DEFAULT CURRENT_TIMESTAMP, "taskId" TEXT NOT NULL, "userId" TEXT, CONSTRAINT "KanbanHistory_pkey" PRIMARY KEY ("id"));

