INSERT INTO "Permission" ("id","code","label","module","createdAt") VALUES
('perm_org_read','organization.read','Ver quadros e tarefas','Organização interna',CURRENT_TIMESTAMP),('perm_org_read_all','organization.read.all','Ver todos os quadros','Organização interna',CURRENT_TIMESTAMP),('perm_org_manage','organization.manage','Gerenciar quadros, colunas e etiquetas','Organização interna',CURRENT_TIMESTAMP),('perm_org_task_create','organization.tasks.create','Criar tarefas','Organização interna',CURRENT_TIMESTAMP),('perm_org_task_edit','organization.tasks.edit','Atualizar tarefas atribuídas','Organização interna',CURRENT_TIMESTAMP),('perm_org_task_edit_all','organization.tasks.edit.all','Atualizar todas as tarefas','Organização interna',CURRENT_TIMESTAMP),('perm_org_task_comment','organization.tasks.comment','Comentar em tarefas','Organização interna',CURRENT_TIMESTAMP) ON CONFLICT ("code") DO NOTHING;
INSERT INTO "RolePermission" ("roleId","permissionId") SELECT r."id",p."id" FROM "Role" r CROSS JOIN "Permission" p WHERE (r."name"='ADMIN' AND p."code" LIKE 'organization.%') OR (r."name"='MANAGER' AND p."code" LIKE 'organization.%') OR (r."name" IN ('WAREHOUSE','PRODUCTION') AND p."code" IN ('organization.read','organization.read.all','organization.tasks.create','organization.tasks.edit','organization.tasks.comment')) OR (r."name"='REQUESTER' AND p."code" IN ('organization.read','organization.tasks.create','organization.tasks.edit','organization.tasks.comment')) OR (r."name"='VIEWER' AND p."code"='organization.read') ON CONFLICT DO NOTHING;
